def geri_tepme(taban, verim_artisi, kullanim_artisi):
    beklenen = taban * verim_artisi
    yeni = taban * (1 - verim_artisi) * (1 + kullanim_artisi)
    gercek = taban - yeni
    oran = (beklenen - gercek) / beklenen
    return round(gercek, 1), round(oran * 100, 1)


for v, k in [(0.20, 0.00), (0.20, 0.08), (0.20, 0.25), (0.20, 0.30)]:
    g, o = geri_tepme(1000000, v, k)
    print(int(g), o)
